import { Component } from 'react'
import PropTypes from 'prop-types'
import Modal from '../Modal'
import { LANG_STRINGS } from '../../lang'
import { LOGIN_AGENT_GOLD } from '../../images'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import Button from '../Button'
import { DisplayFlexCCC, Row } from '../../commonStyle/index.style'

class WarningModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    hideCloseBtn: PropTypes.bool,
    hideIcon: PropTypes.bool,
    warning: PropTypes.string,
    icon: PropTypes.string,
    okText: PropTypes.string,
    title: PropTypes.string,
    onClose: PropTypes.func,
    onOk: PropTypes.func
  }

  render () {
    const {
      showModal, onClose, icon, title, warning,
      onOk, okText, hideCloseBtn, hideIcon
    } = this.props
    return (
      <Modal
        isOpen={showModal}
        onClose={onClose}
        heading={LANG_STRINGS.information}
      >
        <DisplayFlexCCC>
          {
            !hideIcon && (
              <img src={icon || LOGIN_AGENT_GOLD} alt='' />
            )
          }
          {
            title && (
              <CustomText
                top='10px'
                bottom='10px'
                size='18px'
                color={AgentColorPallette.black}
                weight={800}
                textAlign='center'
                className='warning-title'
              >
                {title}
              </CustomText>
            )
          }
          <CustomText
            size='14px'
            bottom='20px'
            lineHeight={1.5}
            color={AgentColorPallette.black}
            textAlign='center'
            dangerouslySetInnerHTML={{
              __html: warning
            }}
          />
          <Row justify='space-between' width='100%'>
            {
              !hideCloseBtn && (
                <>
                  <Button
                    onClick={onClose}
                    backgroundColor={AgentColorPallette.blue}
                    color={AgentColorPallette.white}
                  >
                    {LANG_STRINGS.cancel}
                  </Button>
                  &nbsp;&nbsp;&nbsp;&nbsp;
                </>
              )
            }
            <Button onClick={onOk}>
              {okText || LANG_STRINGS.okay}
            </Button>
          </Row>
        </DisplayFlexCCC>
      </Modal>
    )
  }
}

export default WarningModal
