import {
  resetError,
  useErrorContextValue,
} from '@pasarpolis/common-react-hooks'
import moment from 'moment'
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import NumberFormat from 'react-number-format'
import { useHistory, useLocation, useRouteMatch } from 'react-router'
import { withRouter } from 'react-router-dom'
import {
  BottomActionContainerStyle,
  Row,
} from '../../../../../commonStyle/index.style'
import { CustomText, InnerForm, Select } from '../../../../../components'
import BottomSheetSelect from '../../../../../components/BottomSheetSelect'
import ButtonWithIcon from '../../../../../components/ButtonWithIcon'
import DobInput from '../../../../../components/DobInput'
import HardCopySection from '../../../../../components/HardCopySection'
import NumericInput from '../../../../../components/NumericInput'
import ImageGuideModal from '../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import RadioInputCard from '../../../../../components/RadioInputCard'
import ShowSnackbar from '../../../../../components/ShowNotification'
import StepsHeader from '../../../../../components/StepsHeader'
import TitleError from '../../../../../components/TitleError'
import WarningModal from '../../../../../components/WarningModal'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  clearLocalStorage,
  getFromLocalStorageData,
  setToLocalStorage,
} from '../../../../../helpers/localstorage'
import {
  getConvertedCurrency,
  getIDRCurrency,
} from '../../../../../helpers/utility'
import { typeValid } from '../../../../../helpers/validations'
import { ARROW_RIGHT_ICON } from '../../../../../images'
import { ERROR_LANG, LANG_STRINGS } from '../../../../../lang'
import PolicyModification from '../../components/PolicyModification'
import PolicyOfflineAddons from '../../components/PolicyOfflineAddons'
import PolicyProviderForm from '../../components/PolicyProviderForm'
import { usePolicyContextValue } from '../../context'
import {
  useGetAllProvider,
  useGetConversionRate,
  useUpdateOfflineQuote,
  useValidateChassisNumber,
  useValidatePostalCode,
} from '../../state/hooks/usePolicyState'
import { OFFLINE_MANUAL_FORM_DATA } from '../OfflineProductManualOrder/constant'
import AutoCalculate from './component/AutoCalculate'
import AutoSearchModalComp from './component/AutoSearchModalComp'
import LossRecordForm from './component/LossRecordForm'
import UploadImageComp from './component/MultipleImage'
import {
  getDisabledFields,
  getDobFmt,
  getProtectionType,
  getRelevantError,
  getRespectiveGuideData,
  mapCurrencyType,
  mapLocationStateToFormState,
  modifyKey,
} from './constant'
import {
  NPWPStyleWrapper,
  OfflineFormActionBtn,
  OfflinePolicyFormStyle,
} from './index.style'

const DEFAULT_FORM_DATA = {
  currency_label: 'IDR',
  exchange_rate: '1',
  currency_symbol: 'Rp',
  addons: {},
}

function OfflinePolicyForm({ data, productCode, productName }) {
  const history = useHistory()
  const location = useLocation()
  const match = useRouteMatch()
  const innerFormRef = useRef({})
  const postalCodeRef = useRef({
    error: '',
    isPostalCodeError: false,
  })
  const validateChassisRef = useRef({
    apiCount: 3,
    clearChassisTimeOut: '',
  })
  const autoSearchModalRef = useRef({})
  const disabledFields = useRef([])

  const offlinePolicyLocalData = useRef(
    getFromLocalStorageData(OFFLINE_MANUAL_FORM_DATA, DEFAULT_FORM_DATA)
  )
  const urlParams = useMemo(() => match?.params || {}, [match?.params])
  const isEditPage = useMemo(
    () => location.pathname.includes('edit'),
    [location]
  )
  const packageType = useMemo(() => location?.state?.package_type, [location])

  const [, setState] = useState(false)
  const [showImgModal, setShowImgModal] = useState({})
  const [isChassisValid, setChassisValid] = useState(true)
  const [accessoryError, setAccessoryError] = useState(undefined) // object
  const [{ validateChassisNoData = {} }, validateChassisNoReq] =
    useValidateChassisNumber()
  const [warningModal, setWarningModal] = useState({
    content: '',
    show: false,
    hideClose: true,
  })
  const {
    label,
    serial_no: serialNo,
    total_steps: totalSteps,
    header_text: headerText,
    steps,
    footer_text: footerText,
  } = data

  const [, getAllProviderRequest] = useGetAllProvider()
  const [, validatePostalCodeReq] = useValidatePostalCode()
  const [, getConversionRateDataRequest] = useGetConversionRate()
  const [, updateOfflineQuoteReq] = useUpdateOfflineQuote()
  const [
    {
      getProviderListData = [],
      manualFleetFormErrors,
      getConversionRateData,
      addons = { ...(offlinePolicyLocalData.current.addons || {}) },
      customAddons = {
        custom_add_on: offlinePolicyLocalData.current.custom_add_on,
      },
    },
    ,
    dispatchSetPolicyState,
  ] = usePolicyContextValue()
  const [
    {
      validatePostalCodeStatus,
      validateChassisNoStatus,
      updateOfflineQuoteStatus,
    },
    dispatchError,
  ] = useErrorContextValue()

  const getDefaultValues = useCallback(() => {
    const steps = data?.steps || []
    innerFormRef.current = {}
    let defaultValues = {}
    for (let index = 0; index < steps.length; index++) {
      const step = steps[index]
      const res = step?.fields?.reduce(
        (acc, { name, default_selected: defaultSelected }) => {
          if (defaultSelected) {
            acc[name] = defaultSelected
          }
          return acc
        },
        {}
      )
      defaultValues = { ...defaultValues, ...res }
    }
    return defaultValues
  }, [data])

  const that = useRef({
    product_key: productCode,
    protection_case: 'manual-order',
    ...offlinePolicyLocalData.current,
    exchange_rate_from: 'PPIB',
    ...getDefaultValues(),
    package_type: packageType,
  })

  useEffect(() => {
    const protectionType = getProtectionType(
      location?.state?.purchaseType,
      location?.state?.isSameAgent
    )
    // On page load: Init formData with data from previous page
    if (location.state?.vehicleData) {
      const formState = mapLocationStateToFormState(location.state)
      that.current = {
        ...that.current,
        ...formState,
        protection_type: protectionType,
      }
      setToLocalStorage(OFFLINE_MANUAL_FORM_DATA, that.current)
      disabledFields.current = getDisabledFields(
        that.current.purchase_renew_flow,
        that.current.org_is_expired
      )
      // Remove data from state after init, to prevent multiple init on re-renders
      history.replace({
        ...location,
        state: { ...location.state, vehicleData: null },
      })
    } else {
      that.current = { ...that.current, protection_type: protectionType }
      setToLocalStorage(OFFLINE_MANUAL_FORM_DATA, that.current)
      disabledFields.current = getDisabledFields(
        that.current.purchase_renew_flow,
        that.current.org_is_expired
      )
    }
  }, [location, history])

  useEffect(() => {
    function resetErrorKey(key) {
      dispatchError(
        resetError({
          [key]: undefined,
        })
      )
    }

    if (updateOfflineQuoteStatus === 'success') {
      history.goBack()
      clearLocalStorage()
      resetErrorKey('updateOfflineQuoteStatus')
    } else if (updateOfflineQuoteStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateOfflineQuoteStatus,
      })
      resetErrorKey('updateOfflineQuoteStatus')
    }
  }, [history, dispatchError, updateOfflineQuoteStatus])

  const createSectionWiseData = useCallback(() => {
    if (isEditPage) {
      return offlinePolicyLocalData?.current.reviewFormData
    }
    if (data) {
      const protectionCode = that.current?.protection_type?.code
      const reviewFormData = {
        [`step_${serialNo}`]: {
          page_heading: data?.label,
          section: data?.steps?.map((item) => {
            return {
              section_heading: item.label,
              section_data: item.fields
                ?.map(
                  ({
                    display_label: displayLabel,
                    name,
                    type,
                    review_display_key: reviewDisaplayLabel,
                    protection_required: protectionRequired,
                  }) => {
                    if (
                      protectionRequired &&
                      !protectionRequired?.includes(protectionCode)
                    ) {
                      return null
                    }
                    return {
                      displayLabel,
                      name: reviewDisaplayLabel || name,
                      type,
                    }
                  }
                )
                .filter(Boolean),
            }
          }),
        },
      }
      const isReviewFormAvailable = getFromLocalStorageData(
        OFFLINE_MANUAL_FORM_DATA
      )?.reviewFormData
      if (isReviewFormAvailable) {
        return {
          ...isReviewFormAvailable,
          ...reviewFormData,
        }
      } else {
        return { ...reviewFormData }
      }
    }
  }, [data, isEditPage, serialNo])

  useEffect(() => {
    that.current = {
      ...getDefaultValues(),
      ...that.current,
    }
  }, [data, getDefaultValues])

  useEffect(() => {
    if (that.current.code === 'offline-car-protection-tlo') {
      that.current.package_type = 'car-protection-tlo'
    } else {
      that.current.package_type = packageType
    }
  }, [packageType, that.current.code])

  const updateAddressPostalCodeError = useCallback((error, name) => {
    if (innerFormRef.current[name].setState) {
      innerFormRef.current[name].setState(({ errorField = {} }) => {
        return {
          errorField: {
            ...errorField,
            [name]: error,
          },
        }
      })
    }
  }, [])

  const validateChassis = useCallback(
    (chassisNumber) => {
      validateChassisNoReq({
        body: {
          code: that.current.code,
          pre_validate_data: {
            chasis_number: {
              chasis_number: chassisNumber,
              start_date: that.current?.coverage_period_start,
            },
          },
        },
      })
    },
    [validateChassisNoReq]
  )

  useEffect(() => {
    if (validatePostalCodeStatus === 'success') {
      postalCodeRef.current.error = ''
      postalCodeRef.current.isPostalCodeError = false
      dispatchError(
        resetError({
          validatePostalCodeStatus: '',
        })
      )
    } else if (validatePostalCodeStatus) {
      postalCodeRef.current.error = validatePostalCodeStatus
      postalCodeRef.current.isPostalCodeError = true
      updateAddressPostalCodeError(
        validatePostalCodeStatus,
        'customer_address.postal_code'
      )
      dispatchError(
        resetError({
          validatePostalCodeStatus: '',
        })
      )
    }
  }, [validatePostalCodeStatus, dispatchError, updateAddressPostalCodeError])

  useEffect(() => {
    // validate chassis number
    if (validateChassisNoStatus === 'success') {
      // check is data is ok if not then show error
      if (!validateChassisNoData.success) {
        setChassisValid(false)
      } else if (validateChassisNoData.is_request_pending) {
        validateChassisRef.current.clearChassisTimeOut = setTimeout(() => {
          validateChassis(that.current.chasis_number)
        }, 20000)
      } else {
        setChassisValid(true)
      }
      dispatchError(
        resetError({
          validateChassisNoStatus: '',
        })
      )
    } else if (validateChassisNoStatus) {
      if (!validateChassisRef.current.apiCount) {
        ShowSnackbar.error({
          visible: true,
          text: validateChassisNoStatus,
        })
      } else {
        validateChassisRef.current.apiCount -= 1
        validateChassis(that.current.chasis_number)
      }
      dispatchError(
        resetError({
          validateChassisNoStatus: '',
        })
      )
    }
  }, [
    validateChassis,
    dispatchError,
    validateChassisNoStatus,
    validateChassisNoData,
  ])

  const deleteLocalKeys = useCallback((keys) => {
    keys.forEach((key) => delete that.current[key])
  }, [])

  const isKeyAvailable = useCallback(
    (key) => {
      // search if key is available in response, then no need to make a call
      return data?.steps?.find((section) => {
        return section?.fields?.find((item) => item.name === key)
      })
    },
    [data]
  )

  const isHardCopyFound = useMemo(() => {
    const steps = data?.steps
    return steps?.find((item) =>
      item?.fields.find(({ type }) => type === 'hardCopySection')
    )
  }, [data])

  const isLossRecordFound = useMemo(() => {
    const steps = data?.steps
    return steps?.find((item) =>
      item?.fields.find(({ type }) => type === 'lossRecord')
    )
  }, [data])

  const accessory = useRef({
    accessories: offlinePolicyLocalData.current.accessories || [],
    isModificationChecked: !!offlinePolicyLocalData.current.accessories?.length,
    totalSumInsured: offlinePolicyLocalData.current.totalSumInsured,
  })

  const handleCloseImgModal = useCallback(() => {
    setShowImgModal({
      show: false,
    })
  }, [])

  const handleOnRadioChange = useCallback(
    ({ value }, id, name) => {
      that.current[name] = value
      if (name === 'code') {
        dispatchSetPolicyState({ getProviderListData: [] })
        that.current.providerData = null // TODO
        autoSearchModalRef.current.prov_maps.resetModalState()
        setState((prev) => !prev)
      }
      if (name === 'vehicle_type') {
        autoSearchModalRef.current.year.resetModalState()
        autoSearchModalRef.current.brand.resetModalState()
        autoSearchModalRef.current.model_code.resetModalState()
        dispatchSetPolicyState({
          getBrandListData: [],
          getVariantListData: [],
          getVehicleYearData: [],
        })
        deleteLocalKeys([
          'year',
          'brand',
          'brand_data',
          'model',
          'model_name',
          'model_code',
          'variant',
          'variant_name',
          'variant_code',
          'vehicle_sum_insured',
        ])
        that.current.vehicle_sum_insured = ' '
      }
    },
    [dispatchSetPolicyState, deleteLocalKeys, setState]
  )

  const resetErrorsKey = useCallback(
    (key) => {
      if (manualFleetFormErrors[key]) {
        delete manualFleetFormErrors[key]
        dispatchSetPolicyState({
          manualFleetFormErrors: { ...manualFleetFormErrors },
        })
      } else if (
        manualFleetFormErrors.accessoryError &&
        manualFleetFormErrors.accessoryError[key]
      ) {
        delete manualFleetFormErrors.accessoryError[key]
        dispatchSetPolicyState({
          manualFleetFormErrors: { ...manualFleetFormErrors },
        })
      }
    },
    [dispatchSetPolicyState, manualFleetFormErrors]
  )

  const handleOfflineFormChange = useCallback(
    (val, item, selectedItem = null, error = false) => {
      if (!error) {
        resetErrorsKey(item.name)
      }
      if (
        item.name === 'customer_address.postal_code' &&
        typeValid('postal_code', val)
      ) {
        validatePostalCodeReq({
          body: {
            postal_code: val,
          },
        })
      }
      if (item.name.split(['.']).length > 1) {
        const parentKey = item.name.split(['.'])[0]
        const childKey = item.name.split('.')[1]
        if (!that.current[parentKey]) {
          that.current[parentKey] = {}
        }
        if (parentKey === 'customer_address') {
          val = selectedItem ? { ...selectedItem } : { [childKey]: val }
          that.current[parentKey] = {
            ...that.current[parentKey],
            ...val,
          }
          if (childKey === 'province_code') {
            dispatchSetPolicyState({ getCitiesData: [] })
            autoSearchModalRef.current[
              'customer_address.city_code'
            ].resetModalState()
            delete that.current.customer_address.city_code
            delete that.current.customer_address.city_name
          }
        } else {
          that.current[parentKey][childKey] =
            typeof val === 'object' ? val[item.name] : val
        }
      } else if (item.name === 'year') {
        dispatchSetPolicyState({
          getBrandListData: [],
          getVariantListData: [],
        })
        that.current.year = val
        autoSearchModalRef.current.brand.resetModalState()
        autoSearchModalRef.current.model_code.resetModalState()
        deleteLocalKeys([
          'brand',
          'brand_data',
          'model',
          'model_name',
          'model_code',
          'variant',
          'variant_name',
          'variant_code',
          'vehicle_sum_insured',
        ])
        that.current.vehicle_sum_insured = ' '
      } else if (item.name === 'construction_class') {
        const { class_type: classType, ...rest } = selectedItem
        that.current = {
          ...that.current,
          ...rest,
          [item.name]: classType,
        }
      } else if (item.name === 'occupation_code') {
        that.current = {
          ...that.current,
          ...selectedItem,
        }
      } else if (item.name === 'model_code') {
        const { price, ...rest } = selectedItem
        that.current.vehicle_sum_insured = Number(
          getConvertedCurrency(price, that.current?.exchange_rate)
        )
        that.current = {
          ...that.current,
          ...rest,
          model: rest?.model_code,
          variant: rest?.variant_name,
        }
        that.current.vehiclePrice = price
        setState((prev) => !prev)
      } else if (item.name === 'province_code') {
        dispatchSetPolicyState({ getCitiesData: [] })
        autoSearchModalRef.current.city_code.resetModalState()
        delete that.current.city_code
        delete that.current.city_name
        that.current = {
          ...that.current,
          ...selectedItem,
        }
      } else if (item.name === 'city_code') {
        that.current = {
          ...that.current,
          ...selectedItem,
        }
      } else if (item.name === 'vehicle_sum_insured') {
        that.current[item.name] = Number(val)
        setState((prev) => !prev)
      } else if (item.name === 'brand' && item.type === 'autoSearchModal') {
        dispatchSetPolicyState({ getVariantListData: [] })
        that.current[item.name] = val
        that.current.brand_data = selectedItem
        autoSearchModalRef.current.model_code.resetModalState()
        deleteLocalKeys([
          'model',
          'model_name',
          'model_code',
          'variant',
          'variant_name',
          'variant_code',
          'vehicle_sum_insured',
        ])
        that.current.vehicle_sum_insured = ' '
      } else if (item.name === 'prov_maps') {
        that.current.providerData = val
      } else if (item.name === 'coverage_period') {
        that.current.coverage_period = Number(val)
        const startDate = that.current.coverage_period_start
        if (startDate) {
          const endDate = moment(startDate, 'YYYY-MM-DD').add(
            Number(val) || 1,
            'year'
          )._d
          that.current.coverage_period_end = getDobFmt(endDate)
        }
        setState((prev) => !prev)
      } else if (item.name === 'coverage_period_start') {
        const endDate = moment(val, 'DD/MM/YYYY').add(
          that.current.coverage_period || 1,
          'year'
        )._d
        const startDate = val
        that.current.coverage_period_end = getDobFmt(endDate)
        that.current.coverage_period_start = getDobFmt(startDate)
        setState((prev) => !prev)
      } else if (
        [
          'building_value',
          'building_content_value',
          'machine_value',
          'stock_value',
        ].includes(item.name)
      ) {
        that.current[item.name] = val
        setState((prev) => !prev)
      } else if (
        item.type === 'date' &&
        item.name !== 'coverage_period_start'
      ) {
        that.current[item.name] = getDobFmt(val)
      } else if (item.name === 'chasis_number') {
        if (
          validateChassisRef.current.clearChassisTimeOut &&
          val !== that.current?.[item.name]
        ) {
          clearTimeout(validateChassisRef.current.clearChassisTimeOut)
        }
        that.current[item.name] = val
      } else {
        that.current[item.name] = val
      }
    },
    [
      dispatchSetPolicyState,
      resetErrorsKey,
      validatePostalCodeReq,
      deleteLocalKeys,
    ]
  )

  const renderFormTitle = (title, showGuideBtn, type) => {
    // render the title for each section
    return (
      <Row align="center" justify="space-between">
        <CustomText size="15px" color={AgentColorPallette.regular} weight={700}>
          {title}
        </CustomText>
        {showGuideBtn && (
          <CustomText
            color={AgentColorPallette.darkerGold}
            weight={700}
            onClick={(e) => handleGuideOnClick(type)}
          >
            {LANG_STRINGS.guide}
          </CustomText>
        )}
      </Row>
    )
  }

  const renderFormLabel = useCallback(
    (item) => {
      const isFilled = that.current[item.name]
      return (
        <TitleError
          title={item.label}
          error={
            manualFleetFormErrors[item.name] && !isFilled
              ? LANG_STRINGS.required
              : ''
          }
          required={item.required}
        />
      )
    },
    [manualFleetFormErrors]
  )

  const handlePolicyProviders = (key, value) => {
    // if (key === 'providerData') { // TODO
    //   value = value
    // }
    that.current[key] = value
  }

  const getPolicySectionData = useCallback((key, value) => {
    that.current[key] = value
  }, [])

  const renderPolicyProviders = useCallback(
    (item) => {
      return (
        <PolicyProviderForm
          providerCode={that.current?.code}
          productCode={productCode}
          resetErrorsKey={resetErrorsKey}
          preFilledData={{ ...offlinePolicyLocalData.current, ...that.current }}
          providerAutoRef={(el) => {
            autoSearchModalRef.current[item.name] = el
          }}
          getProviderListData={getProviderListData}
          getPolicySectionData={(key, value) =>
            handlePolicyProviders(key, value)
          }
          manualFleetFormErrors={manualFleetFormErrors}
          getAllProviderRequest={getAllProviderRequest}
          errorField={manualFleetFormErrors.providerData ? 'providerData' : ''}
        />
      )
    },
    [
      manualFleetFormErrors,
      resetErrorsKey,
      getProviderListData,
      productCode,
      getAllProviderRequest,
    ]
  )

  const renderLossRecord = useCallback(() => {
    return (
      <LossRecordForm
        getPolicySectionData={getPolicySectionData}
        defaultValue={that.current?.loss_record_doc}
      />
    )
  }, [getPolicySectionData])

  const renderAutoSearchModal = useCallback(
    (item) => {
      return (
        <AutoSearchModalComp
          data={data}
          fieldData={item}
          renderFormLabel={() => renderFormLabel(item)}
          ref={autoSearchModalRef}
          manualFleetFormErrors={manualFleetFormErrors}
          preFilledData={that}
          handleOfflineFormChange={handleOfflineFormChange}
          productCode={productCode}
          isKeyAvailable={isKeyAvailable}
          disabled={item.disabled}
        />
      )
    },
    [
      handleOfflineFormChange,
      manualFleetFormErrors,
      renderFormLabel,
      productCode,
      isKeyAvailable,
      data,
    ]
  )

  const handleDateRangeError = useCallback(
    (showError, key) => {
      dispatchSetPolicyState({
        manualFleetFormErrors: { [key]: showError },
      })
    },
    [dispatchSetPolicyState]
  )

  const renderDate = useCallback(
    (item) => {
      return (
        <>
          {renderFormLabel(item)}
          <DobInput
            errorField={manualFleetFormErrors[item.name] ? item.name : ''}
            name={item.name}
            showCalenderIcon
            onDobSelect={(val, error) =>
              handleOfflineFormChange(val, item, null, error)
            }
            minDate={Date.now()}
            maxDate={
              moment(Date.now()).add(item?.constraints?.max_value, 'day')._d
            }
            defaultValue={
              that.current[item.name]
                ? moment(that.current[item.name]).format('DD-MM-YYYY')
                : ''
            }
            placeholder={item?.placeholder}
            disabled={item.disabled}
            dateRangeError={(val) => handleDateRangeError(val, item.name)}
          />
          {item.description && (
            <CustomText color={AgentColorPallette.fontDarkerGrey} size="11px">
              {item.description}
            </CustomText>
          )}
          {!manualFleetFormErrors[item.name] &&
            that.current.coverage_period_start && (
              <CustomText color={AgentColorPallette.fontDarkerGrey} size="11px">
                {LANG_STRINGS.policyEndDate}:{' '}
                {moment(that.current?.coverage_period_end).format('DD/MM/YYYY')}
              </CustomText>
            )}
        </>
      )
    },
    [
      handleOfflineFormChange,
      manualFleetFormErrors,
      renderFormLabel,
      handleDateRangeError,
    ]
  )

  const renderDropDown = useCallback(
    (item) => {
      return (
        <>
          {renderFormLabel(item)}
          <Select
            options={item.field_option}
            name={item.name}
            value={that.current[item.name]}
            displayKey="title"
            dataKey="value"
            placeholder={item.label}
            disabled={item.disabled}
            errorField={manualFleetFormErrors[item.name] ? item.name : ''}
            border
            onChange={(val) => handleOfflineFormChange(val, item)}
          />
        </>
      )
    },
    [handleOfflineFormChange, manualFleetFormErrors, renderFormLabel]
  )

  const renderIntegerInput = useCallback(
    (item) => {
      return (
        <>
          {renderFormLabel(item)}
          <NumericInput
            type={item.type}
            name={item.name}
            id={item.id}
            className="number-box-shadow"
            placeholder={item.placeholder}
            disabled={item.disabled}
            maxValue={item?.constraints?.max_value}
            onChange={(val) => handleOfflineFormChange(val, item)}
            errorField={manualFleetFormErrors[item.name] ? item.name : ''}
            defaultValue={that.current[item.name]}
            value={that.current[item.name]}
            amountPrefix={that.current?.currency_symbol}
            currencySymbol={that.current?.currency_symbol}
          />
          {item.description && (
            <CustomText color={AgentColorPallette.fontDarkerGrey} size="11px">
              {item.description}
            </CustomText>
          )}
        </>
      )
    },
    [handleOfflineFormChange, manualFleetFormErrors, renderFormLabel]
  )

  const renderPolicyOfflineAddOns = useCallback(() => {
    return (
      <PolicyOfflineAddons
        selectedAddons={addons || that.current.addons || {}}
        selectedCustomAddons={customAddons || that.current.custom_add_on || {}}
        preFilledAddons={addons || that.current.addons || {}}
        preFilledCustomAddons={customAddons || that.current.custom_add_on || {}}
        resetErrorsKey={resetErrorsKey}
        currencyType={mapCurrencyType(that.current)}
        paddingNotRequired
      />
    )
  }, [addons, customAddons, resetErrorsKey])

  const handleAccessories = useCallback((data) => {
    accessory.current = data
    that.current = {
      ...that.current,
      ...data,
    }
  }, [])

  const renderPolicyModifications = useCallback(() => {
    return (
      <PolicyModification
        onChangeAccessories={handleAccessories}
        defaultData={that.current.accessories}
        resetErrorsKey={resetErrorsKey}
        totalSumInsured={that.current.totalSumInsured}
        errorObj={accessoryError}
        currencyType={mapCurrencyType(that.current)}
        paddingNotRequired
      />
    )
  }, [handleAccessories, resetErrorsKey, accessoryError])

  const handleGuideOnClick = useCallback((name) => {
    setShowImgModal({
      show: true,
      ...getRespectiveGuideData(name),
    })
  }, [])

  const handleCurrencyPreClicked = useCallback(() => {
    if (!getConversionRateData) {
      getConversionRateDataRequest({
        query: {
          exchange_rate_from: 'PPIB',
        },
      })
    }
  }, [getConversionRateDataRequest, getConversionRateData])

  const handleSelectCurrencyType = useCallback(
    (data) => {
      getPolicySectionData('currency_label', data?.currency_label)
      getPolicySectionData('exchange_rate', data?.exchange_rate)
      getPolicySectionData('currency_symbol', data?.currency_symbol)
      getPolicySectionData('exchange_rate_from', data?.exchange_rate_from)
      if (that.current?.vehicle_sum_insured) {
        if (data.currency_symbol !== 'IDR') {
          that.current.vehicle_sum_insured = getConvertedCurrency(
            that.current.vehiclePrice,
            data?.exchange_rate
          )
        } else {
          that.current.vehicle_sum_insured = getIDRCurrency(
            that.current.vehiclePrice,
            data?.exchange_rate
          )
        }
      }
      that.current.currency_label = data?.currency_label
      that.current.exchange_rate = data?.exchange_rate
      that.current.currency_symbol = data?.currency_symbol
    },
    [getPolicySectionData, that]
  )

  const renderUploadImage = useCallback(
    (item) => {
      return (
        <UploadImageComp
          fieldData={item}
          handleChange={(val) => handleOfflineFormChange(val, item)}
          errorField={manualFleetFormErrors[item.name] ? item.name : ''}
          that={that}
          renderFormLabel={renderFormLabel}
          manualFleetFormErrors={manualFleetFormErrors}
          disabled={item.disabled}
        />
      )
    },
    [handleOfflineFormChange, manualFleetFormErrors, renderFormLabel]
  )

  const renderCurrency = useCallback(
    (item) => (
      <BottomSheetSelect
        title={LANG_STRINGS.currencyType}
        id="currency_type"
        name={item.name}
        placeholder={item.placeholder}
        disabled={item.disabled}
        error={
          manualFleetFormErrors.currency_label ? LANG_STRINGS.required : ''
        }
        defaultItem={mapCurrencyType(that.current)}
        handlePreClicked={handleCurrencyPreClicked}
        onSelect={handleSelectCurrencyType}
        data={getConversionRateData}
        dataKey={item.data_key}
        displayKey={item.display_key}
        displayBorder
        required
      />
    ),
    [
      getConversionRateData,
      handleCurrencyPreClicked,
      manualFleetFormErrors,
      handleSelectCurrencyType,
    ]
  )

  const renderRadioInputCard = useCallback(
    (item) => {
      let defaultSelected = that.current[item.name]
      if (
        !item.field_option?.some((opt) => opt.id === that.current[item.name])
      ) {
        defaultSelected = item.default_selected
      }
      return (
        <RadioInputCard
          data={item.field_option}
          name={item.label}
          onChange={(val) => handleOnRadioChange(val, item.id, item.name)}
          defaultSelected={defaultSelected}
          title={item.label}
          required={item.required}
          disabled={item.disabled}
          errorField={manualFleetFormErrors[item.name] ? item.name : ''}
          showError={
            manualFleetFormErrors[item.name] ? LANG_STRINGS.required : ''
          }
          fieldName={item.name}
        />
      )
    },
    [handleOnRadioChange, manualFleetFormErrors]
  )

  const renderAutoCalculate = useCallback(
    (item) => {
      return (
        <AutoCalculate
          fieldData={item}
          renderFormLabel={renderFormLabel}
          currencyType={mapCurrencyType(that.current)}
          preFilledData={that.current}
          getPolicySectionData={getPolicySectionData}
        />
      )
    },
    [renderFormLabel, getPolicySectionData]
  )

  const renderNPWPField = useCallback(
    (item) => {
      return (
        <>
          {renderFormLabel(item)}
          <NPWPStyleWrapper error={manualFleetFormErrors[item.name]}>
            <NumberFormat
              name={item.name}
              value={that.current[item.name]}
              onValueChange={({ value }) =>
                handleOfflineFormChange(value, item)
              }
              decimalScale={0}
              placeholder={item.placeholder}
              disabled={item.disabled}
              className="npwp-input"
              format="##.###.###.#-###.###"
            />
          </NPWPStyleWrapper>
        </>
      )
    },
    [renderFormLabel, handleOfflineFormChange, manualFleetFormErrors]
  )

  const handleChassisValidation = useCallback(
    (chassisNumber, key) => {
      if (key === 'chasis_number') {
        validateChassis(chassisNumber)
      }
    },
    [validateChassis]
  )

  const renderFormFields = useCallback(
    (fields) => {
      return fields
        ?.map((item, index) => {
          if (
            item?.protection_required &&
            !(item?.protection_required).includes(
              that.current?.protection_type?.code
            )
          ) {
            return null
          }
          item.disabled = disabledFields.current?.includes(item.name)
          switch (item.type) {
            case 'radio':
              return renderRadioInputCard(item)
            case 'policyProviders':
              return renderPolicyProviders(item)
            case 'autoSearchModal':
              return renderAutoSearchModal(item)
            case 'date':
              return renderDate(item)
            case 'dropdown':
              return renderDropDown(item)
            case 'amount':
            case 'discount':
              return renderIntegerInput(item)
            case 'addons':
              return renderPolicyOfflineAddOns(item)
            case 'checkbox':
              return renderPolicyModifications(item)
            case 'hardCopySection':
              return (
                <HardCopySection
                  preFilledData={that.current}
                  onChange={(data) => {
                    that.current = { ...that.current, ...data }
                    setToLocalStorage(OFFLINE_MANUAL_FORM_DATA, that.current)
                  }}
                />
              )
            case 'uploadImage':
              return renderUploadImage(item)
            case 'currency':
              return renderCurrency(item)
            case 'auto_calculate':
              return renderAutoCalculate(item)
            case 'npwp':
              return renderNPWPField(item)
            case 'lossRecord':
              return renderLossRecord(item)
            default:
              return (
                <>
                  <InnerForm
                    key={index}
                    formData={{
                      fields: [
                        {
                          ...item,
                          ...(item?.constraints || {}),
                          hideGuideIcon: true,
                          skipEmptyCheck: !item.required,
                          defaultValue: modifyKey(that, item.name),
                          className: 'number-box-shadow',
                          error: manualFleetFormErrors[item.name]
                            ? manualFleetFormErrors[item.name]
                            : getRelevantError(item.name),
                        },
                      ],
                    }}
                    ref={(el) => {
                      innerFormRef.current[item.name] = el
                    }}
                    onGuideClick={({ name }) => handleGuideOnClick(name)}
                    onInputChange={(val) => handleOfflineFormChange(val, item)}
                    onUploadChange={(val, name) =>
                      handleOfflineFormChange(val, item, name)
                    }
                    onValidateChassisNumber={(val) =>
                      handleChassisValidation(val, item.name)
                    }
                  />
                  {item.description && (
                    <CustomText
                      color={AgentColorPallette.fontDarkerGrey}
                      size="11px"
                    >
                      {item.description}
                    </CustomText>
                  )}
                </>
              )
          }
        })
        .filter(Boolean)
    },
    [
      handleOfflineFormChange,
      renderDate,
      manualFleetFormErrors,
      renderAutoSearchModal,
      renderDropDown,
      renderIntegerInput,
      renderPolicyProviders,
      renderPolicyOfflineAddOns,
      renderPolicyModifications,
      renderUploadImage,
      renderCurrency,
      handleGuideOnClick,
      renderRadioInputCard,
      renderAutoCalculate,
      renderLossRecord,
      renderNPWPField,
      handleChassisValidation,
    ]
  )

  const validateFormFields = useCallback(() => {
    const validFormFields = []
    const fieldType = {}
    let isValid = true
    const error = {}
    data.steps.forEach((step) =>
      step?.fields?.forEach((field) => {
        const protectionCode = that.current?.protection_type?.code
        let makeUpdate = true
        if (field.required) {
          makeUpdate = field?.protection_required
            ? field?.protection_required?.includes(protectionCode)
            : makeUpdate
          if (makeUpdate) {
            validFormFields.push(field.name)
            fieldType[`${field.name}`] = field.type
          }
        }
      })
    )
    for (let index = 0; index < validFormFields.length; index++) {
      const field =
        validFormFields[index] === 'prov_maps'
          ? 'providerData'
          : validFormFields[index]
      const item = modifyKey(that, field)
      if (field === 'vehicle_plate_no' && !typeValid(field, item)) {
        isValid = false
        error[field] = item ? ERROR_LANG.incorrectFormat : LANG_STRINGS.required
      } else if (fieldType[field] === 'date' && manualFleetFormErrors[field]) {
        isValid = false
        error[field] = 'Invalid'
      } else if (that.current.isCoinsurance && field === 'providerData') {
        if (that.current.isCoinsurance && !item) {
          isValid = false
          ShowSnackbar.error({
            visible: true,
            text: LANG_STRINGS.noProviderError,
          })
        } else {
          let totalShare = 0
          let isProviderEmpty = true
          let leaderShare
          let isLeaderShareValid = true
          item.forEach((data) => {
            if (data.code && data.code !== '') {
              isProviderEmpty = false
              totalShare += data?.share_percent
              if (data.role === 'LEADER') {
                leaderShare = data.share_percent
              } else if (
                data.role === 'MEMBER' &&
                leaderShare < data.share_percent
              ) {
                isLeaderShareValid = false
              }
            }
          })
          if (totalShare > 100 || isProviderEmpty || !isLeaderShareValid) {
            isValid = false
            ShowSnackbar.error({
              visible: true,
              text: isProviderEmpty
                ? LANG_STRINGS.noProviderError
                : !isLeaderShareValid
                  ? LANG_STRINGS.leaderShareErrorText
                  : LANG_STRINGS.coinsuranceInfoText,
            })
          }
        }
      } else if (!item) {
        isValid = false
        error[field] = true
      }
    }
    dispatchSetPolicyState({
      manualFleetFormErrors: { ...error },
    })
    return isValid
  }, [dispatchSetPolicyState, data, manualFleetFormErrors])

  const handleDynamicRef = async (event) => {
    const dynamicRefs = Object.values(innerFormRef?.current)?.map(
      async (el) => await el?.handleSubmit(event)
    )
    const promises = await Promise.all(dynamicRefs)
    return promises.every(Boolean)
  }

  const handleSubmit = useCallback(
    async (e, step, totalstep) => {
      setAccessoryError(undefined)
      if (!isChassisValid) {
        setWarningModal({
          show: true,
          hideClose: true,
          okText: LANG_STRINGS.understand,
          content: LANG_STRINGS.chassisNumberPolicyAlreadyExist,
        })
        return
      }
      const innerFormData = await handleDynamicRef(e)
      let hardCopyData = {}
      let isValidHardCopy = true
      let isValidLossRecordData = true
      if (isHardCopyFound) {
        hardCopyData = await HardCopySection?.getHardCopyData()
        if (hardCopyData.hard_copy_required && !hardCopyData.isValid) {
          isValidHardCopy = false
        }
      }

      if (isLossRecordFound) {
        let { loss_record_doc: lossRecordDoc } = that.current
        lossRecordDoc = lossRecordDoc.filter(
          (el) => el.loss_record || el.claims
        )
        isValidLossRecordData = !lossRecordDoc.find(
          (el) => !(el.loss_record && el.claims)
        )
        if (!isValidLossRecordData) {
          ShowSnackbar.error({
            visible: true,
            text: ERROR_LANG.lossRecordValidationError,
          })
        }
        that.current = {
          ...that.current,
          loss_record_doc: lossRecordDoc,
        }
      }

      let accessoryErrors = {}
      let isAccessoryValid = true
      if (accessory.current.isModificationChecked) {
        const accessories = accessory.current.accessories || []
        accessories.forEach((acc, index) => {
          if (!acc.name) {
            accessoryErrors[`${acc.key}`] = {
              ...accessoryErrors[`${acc.key}`],
              name: true,
            }
          }
          if (!acc.sum_insured) {
            accessoryErrors[`${acc.key}`] = {
              ...accessoryErrors[`${acc.key}`],
              sum_insured: true,
            }
          }
        })
        if (Object.keys(accessoryErrors).length > 0) {
          dispatchSetPolicyState({
            manualFleetFormErrors: {
              ...manualFleetFormErrors,
              accessoryError: {
                ...manualFleetFormErrors.accessoryError,
                ...accessoryErrors,
              },
            },
          })
          setAccessoryError(accessoryErrors)
          isAccessoryValid = false
        }
      }

      if (
        !(
          validateFormFields() &&
          innerFormData &&
          isValidHardCopy &&
          !postalCodeRef.current.isPostalCodeError &&
          isValidLossRecordData &&
          isAccessoryValid
        )
      ) {
        if (postalCodeRef.current.isPostalCodeError) {
          updateAddressPostalCodeError(
            postalCodeRef.current.error,
            'customer_address.postal_code'
          )
        }
        return
      }
      that.current = {
        ...that.current,
        ...customAddons,
        addons: addons,
      }
      const storageData = {
        ...that.current,
        ...(accessory.current.isModificationChecked
          ? {
              ...accessory.current,
              additional_sum_insured: accessory.current.totalSumInsured,
            }
          : {}),
        reviewFormData: createSectionWiseData(),
        ...hardCopyData,
      }
      setToLocalStorage(OFFLINE_MANUAL_FORM_DATA, storageData)
      that.current = storageData
      if (isEditPage) {
        updateOfflineQuoteReq({
          id: urlParams.quoteId,
          body: storageData,
        })
        return
      }
      if (step < totalstep - 1) {
        history.push({
          pathname: `/${productCode}/form/${step + 1}`,
          state: {
            package_type: packageType,
            name: productName,
            purchaseType: location?.state?.purchaseType,
          },
        })
      } else {
        history.push({
          pathname: `/${productCode}/form/${totalstep}/review`,
          state: {
            package_type: packageType,
            name: productName,
            purchaseType: location?.state?.purchaseType,
          },
        })
      }
      return
    },
    [
      history,
      location,
      urlParams,
      productCode,
      productName,
      packageType,
      addons,
      customAddons,
      validateFormFields,
      createSectionWiseData,
      updateAddressPostalCodeError,
      isHardCopyFound,
      isChassisValid,
      isLossRecordFound,
      isEditPage,
      updateOfflineQuoteReq,
    ]
  )

  const handleChassisModal = useCallback(() => {
    setWarningModal({
      content: '',
      show: false,
      hideClose: true,
    })
  }, [])

  return (
    <>
      {!isEditPage && (
        <StepsHeader
          leftText={label}
          current={serialNo}
          totalSteps={totalSteps ? totalSteps + 1 : 1}
        />
      )}
      <OfflinePolicyFormStyle>
        <div className="info-heading">
          <CustomText size="13px" color={AgentColorPallette.regular}>
            {headerText}
          </CustomText>
        </div>
        {steps?.map((section, index) => (
          <React.Fragment key={index}>
            <div className="form-section">
              {renderFormTitle(
                section.label,
                section.guide,
                section.guide_type
              )}
              {renderFormFields(section.fields)}
            </div>
            {steps.length !== index + 1 && <hr className="separator" />}
          </React.Fragment>
        ))}
      </OfflinePolicyFormStyle>
      <OfflineFormActionBtn>
        {footerText && (
          <BottomActionContainerStyle padding="0">
            <ButtonWithIcon
              className="button-margin"
              text={isEditPage ? LANG_STRINGS.save : footerText}
              icon={ARROW_RIGHT_ICON}
              iconRight
              onClick={(e) => handleSubmit(e, serialNo, totalSteps + 1)}
            />
          </BottomActionContainerStyle>
        )}
      </OfflineFormActionBtn>
      {showImgModal.show && (
        <ImageGuideModal
          showImgModal={showImgModal.show}
          title={showImgModal.modalTitle}
          onClose={handleCloseImgModal}
          modalImgContainer={showImgModal.imgContainer}
          bottomTitle={showImgModal.btmTitle}
        />
      )}
      {warningModal.show && (
        <WarningModal
          hideIcon
          showModal={warningModal.show}
          warning={warningModal.content}
          onOk={handleChassisModal}
          hideCloseBtn={warningModal.hideClose}
          okText={warningModal.okText}
          onClose={handleChassisModal}
        />
      )}
      <ShowSnackbar />
    </>
  )
}

export default withRouter(OfflinePolicyForm)
