import { useEffect, useMemo } from 'react'
import { useRouteMatch } from 'react-router'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Container } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { usePolicyContextValue } from '../../../context'
import { useGetOfflineProductForm } from '../../../state/hooks/usePolicyState'
import OfflinePolicyForm from '../../OfflinePolicyForm/index'
import { OfflineProductManualOrderStyle } from './index.style'

function OfflineProductManualOrderContainer (props) {
  const match = useRouteMatch()
  const { productCode, step } = match?.params

  const productName = useMemo(() => props?.location?.state?.name, [props])
  const [{ getOfflineProductFormData = {} }, getOfflineProductFormReq] = useGetOfflineProductForm()
  const [{ GET_OFFLINE_PRODUCT_FORM_LOADER }] = useLoaderContextValue()
  const [,, dispatchSetPolicyState] = usePolicyContextValue()

  useEffect(() => {
    getOfflineProductFormReq({
      code: productCode,
      serial_no: step
    })
    return () => {
      dispatchSetPolicyState({ getOfflineProductFormData: {} })
    }
  }, [getOfflineProductFormReq, productCode, step, dispatchSetPolicyState])

  return (
    <Container
      title={productName ? `${productName}: ${LANG_STRINGS.manualOrder}` : ''}
      hideBottomTabs
      displayBackButton
      loader={GET_OFFLINE_PRODUCT_FORM_LOADER}
    >
      <OfflineProductManualOrderStyle>
        {productCode && (
          <OfflinePolicyForm
            productCode={productCode}
            productName={productName}
            data={getOfflineProductFormData}
          />
        )}
      </OfflineProductManualOrderStyle>
    </Container>
  )
}

export default OfflineProductManualOrderContainer
