import { useCallback } from 'react'
import { Upload } from '../../../../../../../components'
import BuildImgUpload from '../../../../../../CommonContainer/PropertyDetailForm/components/BuildImgUpload'
import { modifyKey } from '../../constant'
import { BulkImageWrapper } from './index.style'

function UploadImageComp ({
  fieldData = {}, errorField, handleChange, renderFormLabel, that
}) {
  const multipleImageHandler = useCallback((imageCount, url, parentKey) => {
    if (that.current[parentKey]) {
      that.current[parentKey] = {
        ...that.current[parentKey],
        [imageCount]: url
      }
    } else {
      that.current[parentKey] = { [imageCount]: url }
    }
    handleChange(that.current[parentKey])
  }, [
    that, handleChange
  ])

  const renderImageComponent = useCallback(() => {
    const count = fieldData?.constraints?.max_selected || 0
    const { name } = fieldData
    const renderElement = count ? (
      <BulkImageWrapper>
        {
          [...Array(count).keys()]?.map((el, index) => (
            <BuildImgUpload
              title={fieldData.label}
              className={'wrapper'}
              key={`${name}_${index}`}
              name={`${name}_${index}`}
              index={index}
              defaultImg={that.current?.[fieldData.name]?.[`image_${index + 1}`]}
              onUpload={(imgCount, url) => multipleImageHandler(imgCount, url, fieldData.name)}
            />
          ))
        }
      </BulkImageWrapper>
    ) : (
      <Upload
        hideLabel
        displayBorder
        className='upload-wrapper box-shadow'
        label={fieldData.label}
        name={fieldData.name}
        defaultValue={modifyKey(that, fieldData.name)}
        showImg
        onUpload={(val) => handleChange(val)}
        errorField={errorField}
        onlyImg
      />
    )

    return (
      <>
        {renderFormLabel(fieldData)}
        {renderElement}
      </>
    )
  }, [
    errorField, fieldData, handleChange, multipleImageHandler,
    renderFormLabel, that
  ])

  return (
    renderImageComponent()
  )
}

export default UploadImageComp
