import { forwardRef, useCallback, useEffect, useRef } from 'react'
import AutoSearchModal from '../../../../../../../components/AutoSearchModal'
import { LANG_STRINGS } from '../../../../../../../lang'
import { getCategory } from '../../../../constants'
import { usePolicyContextValue } from '../../../../context'
import {
  useGetAllProvider, useGetRegionalCodes, useGetVehicleBrand, useGetVehicleVariant,
  useGetVehicleYear, useGetProvince, useGetCities,
  useGetConstructionData, useGetPropertyOccupationData
} from '../../../../state/hooks/usePolicyState'
import { modifyKey, splitKeys } from '../../constant'

function AutoSearchModalComp ({
  renderFormLabel, autoSearchModalRef, fieldData,
  preFilledData, handleOfflineFormChange, productCode,
  isKeyAvailable, data, disabled
}) {
  const prefillDataForm = useRef(false)
  const [{
    getProviderListData = [], getVehicleYearData = [], getBrandListData = [],
    getVariantListData = [], getRegionCodeData = [], getProvinceData = [],
    getCitiesData = [], manualFleetFormErrors, getPropertyConstructionData = [],
    getPropertyOccupationData = []
  }] = usePolicyContextValue()

  const [, getAllProviderRequest] = useGetAllProvider()
  const [, getVehicleYearRequest] = useGetVehicleYear()
  const [, getBrandListRequest] = useGetVehicleBrand()
  const [, getVariantListRequest] = useGetVehicleVariant()
  const [, getRegionalCodesRequest] = useGetRegionalCodes()
  const [, getProvinceDataRequest] = useGetProvince()
  const [, getCitiesDataRequest] = useGetCities()
  const [, getConstructionDataReq] = useGetConstructionData()
  const [, getPropertyOccupdationReq] = useGetPropertyOccupationData()

  const handlePreClicked = useCallback((key, parentKey = '') => {
    if (parentKey.split('.').length > 1) {
      parentKey = parentKey.split('.')[0]
    }
    // here we call on click of autoseachModal
    if (key === 'prov_maps' && !getProviderListData.length) {
      getAllProviderRequest({
        query: {
          product_code: productCode,
          blacklist: 'offline',
          prov_pg_code: `offline-${preFilledData?.current?.package_type}`,
          active_online_only: 'false'
        }
      })
    } else if (key === 'year' && !getVehicleYearData.length) {
      getVehicleYearRequest()
    } else if (key === 'brand' && !getBrandListData.length) {
      getBrandListRequest({
        year: preFilledData.current.year,
        query: {
          category: getCategory(preFilledData.current.vehicle_type),
          package_type: preFilledData.current.usage
        }
      })
    } else if (key === 'model_code' && !getVariantListData.length) {
      getVariantListRequest({
        params: {
          year: preFilledData.current.year,
          brand: preFilledData.current.brand
        },
        query: {
          category: getCategory(preFilledData.current.vehicle_type),
          package_type: preFilledData.current.usage
        }
      })
    } else if (key === 'region_code' && !getRegionCodeData.length) {
      getRegionalCodesRequest()
    } else if (key === 'province_code' && !getProvinceData.length) {
      getProvinceDataRequest()
    } else if (key === 'city_code' && (preFilledData.current?.province_code || preFilledData.current?.customer_address?.province_code) && !getCitiesData.length) {
      const provinceCode = parentKey === 'customer_address' ? preFilledData.current?.customer_address?.province_code : preFilledData.current?.province_code
      getCitiesDataRequest({
        province: provinceCode
      })
    } else if (key === 'construction_class') {
      getConstructionDataReq()
    } else if (key === 'occupation_code') {
      getPropertyOccupdationReq()
    }
  }, [
    getAllProviderRequest, getProviderListData, getVehicleYearData.length,
    getVehicleYearRequest, getVariantListData, getRegionCodeData, getCitiesDataRequest,
    getRegionalCodesRequest, getProvinceDataRequest, getVariantListRequest, getBrandListData,
    getBrandListRequest, getCitiesData, getProvinceData, getConstructionDataReq, getPropertyOccupdationReq,
    productCode, preFilledData
  ])

  useEffect(() => { // all calls related to autoSearchModal
    const {
      year, brand, vehicle_type: vehicleType, usage, model_code: model,
      region_code: region, customer_address: customerAddress, province_code: province,
      city_code: cityCode, construction_class: constructionClass, occupation_code: occupationCode,
      providerData
    } = preFilledData.current
    if (!prefillDataForm.current && Object.keys(data).length) {
      prefillDataForm.current = true
      if (providerData && isKeyAvailable('prov_maps')) {
        getAllProviderRequest({
          query: {
            product_code: productCode,
            blacklist: 'offline',
            prov_pg_code: `offline-${preFilledData?.current?.package_type}`,
            active_online_only: 'false'
          }
        })
      }
      if (year && isKeyAvailable('year')) {
        getVehicleYearRequest()
      }
      if (brand && isKeyAvailable('brand')) {
        getBrandListRequest({
          year,
          query: {
            category: getCategory(vehicleType),
            package_type: usage
          }
        })
      }
      if (model && isKeyAvailable('model_code')) {
        getVariantListRequest({
          params: {
            year,
            brand
          },
          query: {
            category: getCategory(vehicleType),
            package_type: usage
          }
        })
      }
      if (region && isKeyAvailable('region_code')) {
        getRegionalCodesRequest()
      }
      if (
        (customerAddress?.province_code && isKeyAvailable('customer_address.province_code')) ||
        (province && isKeyAvailable('province_code'))
      ) {
        getProvinceDataRequest()
      }
      if (
        (customerAddress?.city_code && isKeyAvailable('customer_address.city_code')) ||
        (cityCode && isKeyAvailable('city_code'))
      ) {
        getCitiesDataRequest({
          province: customerAddress?.province_code || province
        })
      }
      if (constructionClass && isKeyAvailable('construction_class')) {
        getConstructionDataReq()
      }
      if (occupationCode && isKeyAvailable('occupation_code')) {
        getPropertyOccupdationReq()
      }
    }
  }, [
    getVehicleYearRequest, getBrandListRequest, getVariantListRequest,
    getRegionalCodesRequest, data, isKeyAvailable, getProvinceDataRequest,
    getCitiesDataRequest, getConstructionDataReq, getPropertyOccupdationReq, preFilledData,
    prefillDataForm, getAllProviderRequest, productCode
  ])

  const getFormattedKeyName = useCallback((key) => {
    if (key === 'prov_maps') {
      return 'providerData'
    }
    return key
  }, [])

  const getAutoSearchModalData = useCallback((type) => { // mapping for autosearchModal
    switch (type) {
      case 'prov_maps': return getProviderListData
      case 'year': return getVehicleYearData
      case 'brand': return getBrandListData
      case 'model_code': return getVariantListData
      case 'region_code': return getRegionCodeData
      case 'province_code': return getProvinceData
      case 'city_code': return getCitiesData
      case 'construction_class': return getPropertyConstructionData
      case 'occupation_code': return getPropertyOccupationData
      default: return []
    }
  }, [
    getProviderListData, getVehicleYearData, getBrandListData,
    getVariantListData, getRegionCodeData, getProvinceData,
    getCitiesData, getPropertyOccupationData, getPropertyConstructionData
  ])

  return (
    <>
      {renderFormLabel()}
      <AutoSearchModal
        data={getAutoSearchModalData(splitKeys(fieldData.name))}
        name={fieldData.name}
        errorField={manualFleetFormErrors[fieldData.name === 'prov_maps' ? 'providerData' : fieldData.name] ? fieldData.name : ''}
        placeholder={fieldData.placeholder}
        title={fieldData.label}
        id={fieldData.id}
        displayKey={fieldData.display_key}
        subTitle={fieldData.description}
        dataKey={fieldData.data_key}
        onSelect={(val, t) => handleOfflineFormChange(val, fieldData, t)}
        isMultiple={fieldData.is_multiple}
        defaultProviders={preFilledData.current[getFormattedKeyName(fieldData.name)]}
        defaultValue={modifyKey(preFilledData, fieldData.name)}
        maxSelectCount={fieldData?.constraints?.max_selection}
        titleForMultiple={LANG_STRINGS.selectedProviders}
        handlePreClicked={() => handlePreClicked(splitKeys(fieldData.name), fieldData.name)}
        ref={el => { autoSearchModalRef.current[fieldData.name] = el }}
        showOther={fieldData.showOther}
        disabled={disabled}
      />
    </>
  )
}

export default forwardRef((props, ref) => <AutoSearchModalComp autoSearchModalRef={ref} {...props} />)
