import NumericInput from '../../../../../../../components/NumericInput'
import { CustomText } from '../../../../../../../components'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { AutoCalculateWrapper } from './index.style'

function AutoCalculate ({
  fieldData, renderFormLabel, preFilledData, currencyType, getPolicySectionData
}) {
  const getValue = () => {
    let sum = 0
    sum = fieldData?.constraints?.keys_to_calculate?.reduce((acc, key) => {
      return acc + +(preFilledData[key] || 0)
    }, 0)
    getPolicySectionData('sum_insured', +(sum))
    return sum
  }
  return (
    <AutoCalculateWrapper>
      {renderFormLabel(fieldData)}
      <NumericInput
        type='amount'
        name={fieldData.name}
        id={fieldData.id}
        className='auto-caluclate-input'
        placeholder={fieldData.placeholder}
        maxValue={fieldData?.constraints?.max_value}
        disabled
        value={getValue()}
        defaultValue={getValue()}
        amountPrefix={`${currencyType?.currency_symbol}`}
        onChange={() => {}}
        currencySymbol={currencyType?.currency_symbol}
      />
      {fieldData.description && (
        <CustomText
          color={AgentColorPallette.fontDarkerGrey}
          size='11px'
        >
          {fieldData.description}
        </CustomText>
      )}
    </AutoCalculateWrapper>
  )
}

export default AutoCalculate
