import moment from 'moment'
import { useCallback, useState, useRef } from 'react'
import { DisplayFlexRCSB } from '../../../../../../../commonStyle/index.style'
import { CustomText, Button } from '../../../../../../../components'
import DobInput from '../../../../../../../components/DobInput'
import NumericInput from '../../../../../../../components/NumericInput'
import { AgentColorPallette } from '../../../../../../../configs/colorPallete'
import { getDobFmt } from '../../../../../../../helpers/getPackageBody'
import { POLICY_LANG } from '../../../OfflinePolicyReviewForm/constant'
import { LossRecordStyleWrapper } from './index.style'
import ShowSnackbar from '../../../../../../../components/ShowNotification'
import { ERROR_LANG } from '../../../../../../../lang'

function LossRecordForm ({
  getPolicySectionData,
  defaultValue = ''
}) {
  const lossRecordRef = useRef({})
  const [availableRecord, setAvailbleRecord] = useState(defaultValue || [
    {
      loss_record: '',
      claims: ''
    }
  ])

  const renderFormLabel = useCallback((title) => {
    return (
      <CustomText
        color={AgentColorPallette.regular}
        weight={700}
        size='10px'
      >
        {title}
      </CustomText>
    )
  }, [])

  const addLossRecord = useCallback(() => {
    const updatedLossRecord = [
      ...availableRecord,
      {
        loss_record: '',
        claims: ''
      }

    ]
    setAvailbleRecord(updatedLossRecord)
    getPolicySectionData('loss_record_doc', updatedLossRecord)
  }, [availableRecord, getPolicySectionData])

  const removeLossRecord = useCallback((index) => {
    const updatedLossRecord = [...availableRecord]
    updatedLossRecord.splice(index, 1)
    setAvailbleRecord(updatedLossRecord)
    getPolicySectionData('loss_record_doc', updatedLossRecord)
  }, [availableRecord, getPolicySectionData])

  const isLossRecordInRange = useCallback((value) => {
    const inputDate = moment(value, 'DD/MM/YYYY')
    const minYearRange = getDobFmt(moment(new Date(), 'DD/MM/YYYY').subtract(5, 'year')._d)
    const maxYearRange = getDobFmt(moment(new Date(), 'DD/MM/YYYY').subtract(3, 'year')._d)
    if (inputDate.isBefore(maxYearRange) && inputDate.isAfter(minYearRange)) {
      return true
    }
    return false
  }, [])

  const handleOnChange = useCallback((key, value, index) => {
    const isAlreadyFilled = availableRecord.some(el => value && (el.loss_record === value))
    if (((key === 'loss_record') && value && !isLossRecordInRange(value)) || isAlreadyFilled) {
      lossRecordRef.current[index].resetDate()
      ShowSnackbar.error({
        visible: true,
        text: ERROR_LANG.lossRecordDateMustBeIn3To5Yrs
      })
      return
    }
    const updatedLossRecord = [...availableRecord]
    updatedLossRecord[index] = {
      ...updatedLossRecord[index],
      [key]: value
    }
    setAvailbleRecord(updatedLossRecord)
    getPolicySectionData('loss_record_doc', updatedLossRecord)
  }, [availableRecord, getPolicySectionData, isLossRecordInRange])

  return (
    <LossRecordStyleWrapper>
      {
        availableRecord?.map((item, index) => (
          <DisplayFlexRCSB key={index}>
            <div className='loss-record-field'>
              {renderFormLabel(POLICY_LANG.lossRecord)}
              <DobInput
                name='loss_record'
                showCalenderIcon
                onDobSelect={(val) => handleOnChange('loss_record', val, index)}
                defaultValue={item.loss_record || ''}
                placeholder={item?.placeholder}
                ref={instance => (lossRecordRef.current[index] = instance)}
              />
            </div>
            <div className='loss-record-field'>
              {renderFormLabel(POLICY_LANG.numberOfClaims)}
              <div className='input-box'>
                {
                  availableRecord.length > 1 && index > 0 &&
                    <Button className='remove-provider' onClick={() => removeLossRecord(index)}>
                      x
                    </Button>
                }
                <NumericInput
                  type='amount'
                  name='claims'
                  id={index}
                  className='number-box-shadow'
                  placeholder={item.placeholder}
                  maxValue={item?.constraints?.max_value}
                  onChange={(val) => handleOnChange('claims', val, index)}
                  value={item.claims}
                  defaultValue={item.claims}
                />
              </div>
            </div>
          </DisplayFlexRCSB>
        ))
      }
      <div className='button-container'>
        <Button
          className='add-loss-record-btn'
          onClick={addLossRecord}
          disabled={availableRecord.length === 5}
        >
          {POLICY_LANG.addLossRecord}
        </Button>
      </div>
      <ShowSnackbar hideOkay />
    </LossRecordStyleWrapper>
  )
}

export default LossRecordForm
